-- Additive Student fee ledger and host country-currency master schema.
-- Apply only after a verified recoverable backup. This script is not auto-applied by the API.
-- Creates no fee catalogue rows, payment records, credentials, or role grants.

BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."CountryCurrencyMaster" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CountryId" integer NOT NULL,
    "CurrencyCode" varchar(3) NOT NULL,
    "CurrencyName" varchar(100) NOT NULL,
    "CurrencySymbol" varchar(12) NOT NULL,
    "DecimalPlaces" smallint NOT NULL DEFAULT 2,
    "IsPrimary" boolean NOT NULL DEFAULT false,
    "IsActive" boolean NOT NULL DEFAULT true,
    "EffectiveFrom" date NOT NULL,
    "EffectiveTo" date,
    "AddedByHostUserId" bigint NOT NULL,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedByHostUserId" bigint,
    "UpdatedDateTime" timestamp,
    CONSTRAINT "FK_CountryCurrencyMaster_Country" FOREIGN KEY ("CountryId") REFERENCES skolenza."Country"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_CountryCurrencyMaster_CurrencyCode" CHECK (length("CurrencyCode") = 3),
    CONSTRAINT "CK_CountryCurrencyMaster_DecimalPlaces" CHECK ("DecimalPlaces" IN (0, 2, 3)),
    CONSTRAINT "CK_CountryCurrencyMaster_EffectiveDates" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom")
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_CountryCurrencyMaster_Country_Code_EffectiveFrom"
    ON skolenza."CountryCurrencyMaster" ("CountryId", "CurrencyCode", "EffectiveFrom");
CREATE UNIQUE INDEX IF NOT EXISTS "UX_CountryCurrencyMaster_ActivePrimaryCountry"
    ON skolenza."CountryCurrencyMaster" ("CountryId")
    WHERE "IsPrimary" = true AND "IsActive" = true AND "EffectiveTo" IS NULL;

CREATE TABLE IF NOT EXISTS skolenza."StudentFeeStructure" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "CampusId" bigint NOT NULL,
    "AcademicSessionId" bigint NOT NULL,
    "AcademicGroupId" bigint NOT NULL,
    "CountryCurrencyMasterId" bigint NOT NULL,
    "CurrencyCode" varchar(3) NOT NULL,
    "CurrencyDecimalPlaces" smallint NOT NULL DEFAULT 2,
    "LateFeePerInstallment" numeric(18,3) NOT NULL DEFAULT 0,
    "GracePeriodDays" smallint NOT NULL DEFAULT 0,
    "LateFeeCap" numeric(18,3),
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp,
    CONSTRAINT "FK_StudentFeeStructure_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentFeeStructure_Campus" FOREIGN KEY ("CampusId") REFERENCES skolenza."Campus"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentFeeStructure_Session" FOREIGN KEY ("AcademicSessionId") REFERENCES skolenza."AcademicSessionMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentFeeStructure_Group" FOREIGN KEY ("AcademicGroupId") REFERENCES skolenza."AcademicGroupMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentFeeStructure_Currency" FOREIGN KEY ("CountryCurrencyMasterId") REFERENCES skolenza."CountryCurrencyMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentFeeStructure_LateFee" CHECK ("LateFeePerInstallment" >= 0 AND "GracePeriodDays" >= 0 AND ("LateFeeCap" IS NULL OR "LateFeeCap" >= 0)),
    CONSTRAINT "CK_StudentFeeStructure_CurrencyDecimalPlaces" CHECK ("CurrencyDecimalPlaces" IN (0, 2, 3))
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentFeeStructure_Campus_Session_Group"
    ON skolenza."StudentFeeStructure" ("InstitutionId", "CampusId", "AcademicSessionId", "AcademicGroupId")
    WHERE "IsSoftDeleted" = false;

CREATE TABLE IF NOT EXISTS skolenza."StudentFeeStructureItem" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentFeeStructureId" bigint NOT NULL,
    "FeeComponentMasterId" bigint NOT NULL,
    "ComponentCode" varchar(60) NOT NULL,
    "ComponentName" varchar(150) NOT NULL,
    "ChargeNature" smallint NOT NULL,
    "Amount" numeric(18,3) NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT true,
    CONSTRAINT "FK_StudentFeeStructureItem_Structure" FOREIGN KEY ("StudentFeeStructureId") REFERENCES skolenza."StudentFeeStructure"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentFeeStructureItem_ComponentMaster" FOREIGN KEY ("FeeComponentMasterId") REFERENCES skolenza."StudentFeeComponentMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentFeeStructureItem_Amount" CHECK ("Amount" >= 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentFeeStructureItem_Component"
    ON skolenza."StudentFeeStructureItem" ("InstitutionId", "StudentFeeStructureId", "FeeComponentMasterId");

CREATE TABLE IF NOT EXISTS skolenza."StudentFeeStructureFrequency" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentFeeStructureId" bigint NOT NULL,
    "FeeFrequencyMasterId" bigint NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT true,
    CONSTRAINT "FK_StudentFeeStructureFrequency_Structure" FOREIGN KEY ("StudentFeeStructureId") REFERENCES skolenza."StudentFeeStructure"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentFeeStructureFrequency_FrequencyMaster" FOREIGN KEY ("FeeFrequencyMasterId") REFERENCES skolenza."StudentFeeFrequencyMaster"("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentFeeStructureFrequency_Frequency"
    ON skolenza."StudentFeeStructureFrequency" ("InstitutionId", "StudentFeeStructureId", "FeeFrequencyMasterId");

CREATE TABLE IF NOT EXISTS skolenza."StudentFeeStructureInstallmentDueDate" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentFeeStructureFrequencyId" bigint NOT NULL,
    "InstallmentNumber" smallint NOT NULL,
    "DueDate" date NOT NULL,
    CONSTRAINT "FK_StudentFeeStructureInstallmentDueDate_Frequency" FOREIGN KEY ("StudentFeeStructureFrequencyId") REFERENCES skolenza."StudentFeeStructureFrequency"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentFeeStructureInstallmentDueDate_Number" CHECK ("InstallmentNumber" > 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentFeeStructureInstallmentDueDate_Number"
    ON skolenza."StudentFeeStructureInstallmentDueDate" ("InstitutionId", "StudentFeeStructureFrequencyId", "InstallmentNumber");

CREATE TABLE IF NOT EXISTS skolenza."StudentAdmissionFeeQuote" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentAdmissionId" bigint NOT NULL,
    "StudentFeeStructureId" bigint NOT NULL,
    "StudentFeeStructureFrequencyId" bigint NOT NULL,
    "StudentBenefitSchemeMasterId" bigint,
    "CurrencyCode" varchar(3) NOT NULL,
    "CurrencyDecimalPlaces" smallint NOT NULL DEFAULT 2,
    "DiscountPercent" numeric(5,2) NOT NULL,
    "GrossRecurringAmount" numeric(18,3) NOT NULL,
    "DiscountAmount" numeric(18,3) NOT NULL,
    "OneTimeAmount" numeric(18,3) NOT NULL,
    "NetAnnualAmount" numeric(18,3) NOT NULL,
    "InstallmentsPerYear" smallint NOT NULL,
    "CreatedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "CreatedById" bigint NOT NULL,
    CONSTRAINT "FK_StudentAdmissionFeeQuote_Admission" FOREIGN KEY ("StudentAdmissionId") REFERENCES skolenza."StudentAdmission"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentAdmissionFeeQuote_Structure" FOREIGN KEY ("StudentFeeStructureId") REFERENCES skolenza."StudentFeeStructure"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentAdmissionFeeQuote_Frequency" FOREIGN KEY ("StudentFeeStructureFrequencyId") REFERENCES skolenza."StudentFeeStructureFrequency"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentAdmissionFeeQuote_BenefitScheme" FOREIGN KEY ("StudentBenefitSchemeMasterId") REFERENCES skolenza."StudentBenefitSchemeMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentAdmissionFeeQuote_Amounts" CHECK ("DiscountPercent" BETWEEN 0 AND 100 AND "GrossRecurringAmount" >= 0 AND "DiscountAmount" >= 0 AND "OneTimeAmount" >= 0 AND "NetAnnualAmount" >= 0),
    CONSTRAINT "CK_StudentAdmissionFeeQuote_Installments" CHECK ("InstallmentsPerYear" BETWEEN 1 AND 12),
    CONSTRAINT "CK_StudentAdmissionFeeQuote_CurrencyDecimalPlaces" CHECK ("CurrencyDecimalPlaces" IN (0, 2, 3))
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentAdmissionFeeQuote_Admission"
    ON skolenza."StudentAdmissionFeeQuote" ("InstitutionId", "StudentAdmissionId");

CREATE TABLE IF NOT EXISTS skolenza."StudentAdmissionFeeQuoteLine" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentAdmissionFeeQuoteId" bigint NOT NULL,
    "ComponentCode" varchar(60) NOT NULL,
    "ComponentName" varchar(150) NOT NULL,
    "ChargeNature" smallint NOT NULL,
    "AnnualAmount" numeric(18,3) NOT NULL,
    "DiscountAmount" numeric(18,3) NOT NULL,
    "NetAmount" numeric(18,3) NOT NULL,
    CONSTRAINT "FK_StudentAdmissionFeeQuoteLine_Quote" FOREIGN KEY ("StudentAdmissionFeeQuoteId") REFERENCES skolenza."StudentAdmissionFeeQuote"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentAdmissionFeeQuoteLine_Amounts" CHECK ("AnnualAmount" >= 0 AND "DiscountAmount" >= 0 AND "NetAmount" >= 0 AND "DiscountAmount" <= "AnnualAmount")
);

CREATE TABLE IF NOT EXISTS skolenza."StudentFeeInstallment" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentAdmissionFeeQuoteId" bigint NOT NULL,
    "InstallmentNumber" smallint NOT NULL,
    "DueDate" date NOT NULL,
    "RecurringAmount" numeric(18,3) NOT NULL DEFAULT 0,
    "OneTimeAmount" numeric(18,3) NOT NULL DEFAULT 0,
    "LateFeeAmount" numeric(18,3) NOT NULL DEFAULT 0,
    "PaidAmount" numeric(18,3) NOT NULL DEFAULT 0,
    "Status" smallint NOT NULL,
    CONSTRAINT "FK_StudentFeeInstallment_Quote" FOREIGN KEY ("StudentAdmissionFeeQuoteId") REFERENCES skolenza."StudentAdmissionFeeQuote"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentFeeInstallment_Amounts" CHECK ("RecurringAmount" >= 0 AND "OneTimeAmount" >= 0 AND "LateFeeAmount" >= 0 AND "PaidAmount" >= 0),
    CONSTRAINT "CK_StudentFeeInstallment_Status" CHECK ("Status" BETWEEN 1 AND 5)
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentFeeInstallment_Quote_Number"
    ON skolenza."StudentFeeInstallment" ("InstitutionId", "StudentAdmissionFeeQuoteId", "InstallmentNumber");

CREATE TABLE IF NOT EXISTS skolenza."StudentFeePaymentAttempt" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentFeeInstallmentId" bigint NOT NULL,
    "IdempotencyKey" varchar(100) NOT NULL,
    "GatewayCode" varchar(40) NOT NULL,
    "GatewayOrderId" varchar(100) NOT NULL,
    "GatewayPaymentSessionId" varchar(2000),
    "Amount" numeric(18,3) NOT NULL,
    "CurrencyCode" varchar(3) NOT NULL,
    "Status" smallint NOT NULL,
    "CreatedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ExpiresDateTime" timestamp,
    CONSTRAINT "FK_StudentFeePaymentAttempt_Installment" FOREIGN KEY ("StudentFeeInstallmentId") REFERENCES skolenza."StudentFeeInstallment"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentFeePaymentAttempt_Amount" CHECK ("Amount" > 0),
    CONSTRAINT "CK_StudentFeePaymentAttempt_Status" CHECK ("Status" BETWEEN 1 AND 5)
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentFeePaymentAttempt_Idempotency"
    ON skolenza."StudentFeePaymentAttempt" ("InstitutionId", "IdempotencyKey");
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentFeePaymentAttempt_GatewayOrder"
    ON skolenza."StudentFeePaymentAttempt" ("GatewayOrderId");

CREATE TABLE IF NOT EXISTS skolenza."StudentFeePaymentTransaction" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentFeeInstallmentId" bigint NOT NULL,
    "StudentFeePaymentAttemptId" bigint,
    "GatewayPaymentId" varchar(100),
    "IdempotencyKey" varchar(100),
    "Method" smallint NOT NULL,
    "Status" smallint NOT NULL,
    "Amount" numeric(18,3) NOT NULL,
    "CurrencyCode" varchar(3) NOT NULL,
    "BankReference" varchar(150),
    "RecordedReference" varchar(150),
    "RecordedById" bigint,
    "PaidDateTime" timestamp,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_StudentFeePaymentTransaction_Installment" FOREIGN KEY ("StudentFeeInstallmentId") REFERENCES skolenza."StudentFeeInstallment"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentFeePaymentTransaction_Attempt" FOREIGN KEY ("StudentFeePaymentAttemptId") REFERENCES skolenza."StudentFeePaymentAttempt"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentFeePaymentTransaction_Amount" CHECK ("Amount" > 0),
    CONSTRAINT "CK_StudentFeePaymentTransaction_Method" CHECK ("Method" IN (1, 2)),
    CONSTRAINT "CK_StudentFeePaymentTransaction_Status" CHECK ("Status" BETWEEN 1 AND 5)
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentFeePaymentTransaction_Idempotency"
    ON skolenza."StudentFeePaymentTransaction" ("InstitutionId", "IdempotencyKey") WHERE "IdempotencyKey" IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentFeePaymentTransaction_GatewayPayment"
    ON skolenza."StudentFeePaymentTransaction" ("GatewayPaymentId") WHERE "GatewayPaymentId" IS NOT NULL;

CREATE TABLE IF NOT EXISTS skolenza."StudentFeePaymentWebhookEvent" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StudentFeePaymentAttemptId" bigint NOT NULL,
    "EventId" varchar(150) NOT NULL,
    "EventType" varchar(100) NOT NULL,
    "PayloadSha256" varchar(64) NOT NULL,
    "ProcessingStatus" smallint NOT NULL,
    "ReceivedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ProcessedDateTime" timestamp,
    CONSTRAINT "FK_StudentFeePaymentWebhookEvent_Attempt" FOREIGN KEY ("StudentFeePaymentAttemptId") REFERENCES skolenza."StudentFeePaymentAttempt"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentFeePaymentWebhookEvent_Status" CHECK ("ProcessingStatus" BETWEEN 1 AND 4)
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentFeePaymentWebhookEvent_EventId"
    ON skolenza."StudentFeePaymentWebhookEvent" ("EventId");

CREATE TABLE IF NOT EXISTS skolenza."StudentFeeReceipt" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentFeePaymentTransactionId" bigint NOT NULL,
    "StudentAdmissionFeeQuoteId" bigint NOT NULL,
    "StudentFeeInstallmentId" bigint NOT NULL,
    "ReceiptNumber" varchar(100) NOT NULL,
    "Amount" numeric(18,3) NOT NULL,
    "CurrencyCode" varchar(3) NOT NULL,
    "IssuedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_StudentFeeReceipt_Transaction" FOREIGN KEY ("StudentFeePaymentTransactionId") REFERENCES skolenza."StudentFeePaymentTransaction"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentFeeReceipt_Quote" FOREIGN KEY ("StudentAdmissionFeeQuoteId") REFERENCES skolenza."StudentAdmissionFeeQuote"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentFeeReceipt_Installment" FOREIGN KEY ("StudentFeeInstallmentId") REFERENCES skolenza."StudentFeeInstallment"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentFeeReceipt_Amount" CHECK ("Amount" > 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentFeeReceipt_Institution_Number"
    ON skolenza."StudentFeeReceipt" ("InstitutionId", "ReceiptNumber");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_StudentFeeReceipt_StudentFeePaymentTransactionId"
    ON skolenza."StudentFeeReceipt" ("StudentFeePaymentTransactionId");

-- Upgrade an earlier draft of this additive schema without replacing any fee data.
ALTER TABLE skolenza."CountryCurrencyMaster"
    ADD COLUMN IF NOT EXISTS "DecimalPlaces" smallint NOT NULL DEFAULT 2;
ALTER TABLE skolenza."StudentFeeStructure"
    ADD COLUMN IF NOT EXISTS "CurrencyDecimalPlaces" smallint NOT NULL DEFAULT 2;
ALTER TABLE skolenza."StudentAdmissionFeeQuote"
    ADD COLUMN IF NOT EXISTS "CurrencyDecimalPlaces" smallint NOT NULL DEFAULT 2;
ALTER TABLE skolenza."StudentFeeStructure"
    ALTER COLUMN "LateFeePerInstallment" TYPE numeric(18,3),
    ALTER COLUMN "LateFeeCap" TYPE numeric(18,3);
ALTER TABLE skolenza."StudentFeeStructureItem" ALTER COLUMN "Amount" TYPE numeric(18,3);
ALTER TABLE skolenza."StudentAdmissionFeeQuote"
    ALTER COLUMN "GrossRecurringAmount" TYPE numeric(18,3),
    ALTER COLUMN "DiscountAmount" TYPE numeric(18,3),
    ALTER COLUMN "OneTimeAmount" TYPE numeric(18,3),
    ALTER COLUMN "NetAnnualAmount" TYPE numeric(18,3);
ALTER TABLE skolenza."StudentAdmissionFeeQuoteLine"
    ALTER COLUMN "AnnualAmount" TYPE numeric(18,3),
    ALTER COLUMN "DiscountAmount" TYPE numeric(18,3),
    ALTER COLUMN "NetAmount" TYPE numeric(18,3);
ALTER TABLE skolenza."StudentFeeInstallment"
    ALTER COLUMN "RecurringAmount" TYPE numeric(18,3),
    ALTER COLUMN "OneTimeAmount" TYPE numeric(18,3),
    ALTER COLUMN "LateFeeAmount" TYPE numeric(18,3),
    ALTER COLUMN "PaidAmount" TYPE numeric(18,3);
ALTER TABLE skolenza."StudentFeePaymentAttempt" ALTER COLUMN "Amount" TYPE numeric(18,3);
ALTER TABLE skolenza."StudentFeePaymentTransaction" ALTER COLUMN "Amount" TYPE numeric(18,3);
ALTER TABLE skolenza."StudentFeeReceipt" ALTER COLUMN "Amount" TYPE numeric(18,3);
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'CK_CountryCurrencyMaster_DecimalPlaces') THEN
        ALTER TABLE skolenza."CountryCurrencyMaster"
            ADD CONSTRAINT "CK_CountryCurrencyMaster_DecimalPlaces" CHECK ("DecimalPlaces" IN (0, 2, 3));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'CK_StudentFeeStructure_CurrencyDecimalPlaces') THEN
        ALTER TABLE skolenza."StudentFeeStructure"
            ADD CONSTRAINT "CK_StudentFeeStructure_CurrencyDecimalPlaces" CHECK ("CurrencyDecimalPlaces" IN (0, 2, 3));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'CK_StudentAdmissionFeeQuote_CurrencyDecimalPlaces') THEN
        ALTER TABLE skolenza."StudentAdmissionFeeQuote"
            ADD CONSTRAINT "CK_StudentAdmissionFeeQuote_CurrencyDecimalPlaces" CHECK ("CurrencyDecimalPlaces" IN (0, 2, 3));
    END IF;
END $$;

-- The immutable quote is one-per-admission. Enforce this under concurrent requests too.
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentAdmissionFeeQuote_Admission"
    ON skolenza."StudentAdmissionFeeQuote" ("InstitutionId", "StudentAdmissionId");

-- Host-managed currency master appears in the authenticated Host menu. Operation IDs are resolved dynamically.
INSERT INTO skolenza."Module"
    ("InstitutionId", "ModuleCode", "ModuleName", "PageName", "DisplayName", "URLPath", "ParentModuleId",
     "IsLeafNode", "IsModuleDisplayInUI", "IsCommonMenu", "ModuleScope", "IsActive", "ImageIconWeb",
     "ImageIconMobile", "ItemPriority", "Remark", "AddedById", "AddedDateTime")
SELECT NULL, 'HOST_COUNTRY_CURRENCY_MASTER', 'Host-Country-Currency-Master', 'country-currency-master',
       'Country Currency Master', '/app/host/country-currency-masters', NULL, TRUE, TRUE, FALSE, 2, TRUE,
       'bi bi-currency-exchange', 'currency_exchange', 125, 'Host-owned country to ISO currency mapping used by Campus fee ledgers.',
       1, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM skolenza."Module" WHERE "ModuleCode" = 'HOST_COUNTRY_CURRENCY_MASTER');

INSERT INTO skolenza."ModuleOperationMapping"
    ("ModuleId", "OperationId", "PageURL", "IconURL", "IsCommonItem", "IsOperational", "Priority", "Remark",
     "IsActive", "AddedById", "AddedDateTime")
SELECT module."Id", operation."Id", module."URLPath", COALESCE(operation."IconImage", module."ImageIconWeb"),
       FALSE, TRUE,
       CASE lower(btrim(operation."OperationName"))
           WHEN 'view' THEN 10 WHEN 'add' THEN 20 WHEN 'update' THEN 30 WHEN 'delete' THEN 40 ELSE 99 END,
       operation."OperationName" || ' Country Currency Master.', TRUE, 1, CURRENT_TIMESTAMP
FROM skolenza."Module" module
JOIN skolenza."Operation" operation
  ON lower(btrim(operation."OperationName")) IN ('view', 'add', 'update', 'delete') AND operation."IsActive"
WHERE module."ModuleCode" = 'HOST_COUNTRY_CURRENCY_MASTER'
  AND NOT EXISTS (
      SELECT 1 FROM skolenza."ModuleOperationMapping" existing
      WHERE existing."ModuleId" = module."Id" AND existing."OperationId" = operation."Id"
  );

COMMIT;
